import {triagePanel,contextControls,renderContext} from './guidance.js?v=0.4.0';
import {lessons,recipes,workflows,commands,sources} from '../content.js?v=0.4.0';
import {e,sourceLink,command,breadcrumb,pageHead,lessonCard,problemCard,workflowCard,notFound} from '../ui.js?v=0.4.0';
import {MAX_INPUT} from '../analyser.js?v=0.4.0';
export function fix({draft,activeFilter,triage}={}){return pageHead('FIX / DIAGNOSE BEFORE YOU CHANGE','Let’s find your next check.','Choose a problem below, or paste a sanitised error. Start with the evidence and keep the target environment in view.')+`${triagePanel(triage)}<section class="analyser" aria-labelledby="analyser-heading"><div class="section-heading"><div><h2 id="analyser-heading">What is Terraform telling you?</h2><p>Local pattern matching · Pasted text stays in tab memory and is never sent by this analyser.</p></div></div><label class="sr-only" for="error-input">Sanitised Terraform error output</label><textarea id="error-input" placeholder="Paste a sanitised error here…\nFor example: Error: Error acquiring the state lock" spellcheck="false" aria-describedby="input-guidance">${e(draft.text)}</textarea><p class="small" id="input-guidance">Remove secrets and personal details. Paste error text only; do not paste state or saved-plan contents. Limit: ${MAX_INPUT.toLocaleString()} characters.</p><details><summary>Add context (optional)</summary>${contextControls(draft)}<p>Context stays in this tab. Provider, backend and execution settings are independent; they do not override matched evidence.</p></details><div class="analyser-actions"><div><button class="button primary small" id="analyse">Find relevant guidance →</button> <button class="button small" id="clear-input">Clear</button></div><div class="sample-buttons" role="group" aria-label="Try a sample error"><span class="small muted" style="padding:7px">Try a sample:</span><button data-sample="lock">State lock</button><button data-sample="provider">Provider</button><button data-sample="variable">Variable</button><button data-sample="cycle">Cycle</button></div></div><div id="analysis-status" class="sr-only" role="status" aria-label="Diagnostic summary" aria-live="polite" aria-atomic="true"></div><div id="analysis-results" role="region" aria-label="Diagnostic guidance"></div></section><section aria-labelledby="browse-problems"><div class="section-heading"><div><h2 id="browse-problems">Find a problem by symptom</h2><p>No paste needed. Every guide includes checks, verification and a stop condition.</p></div></div><div class="filter-row" role="group" aria-label="Filter by failing phase">${[['all','All problems'],['setup','Setup'],['init','Initialise'],['validate','Validate'],['plan','Plan'],['apply','Apply'],['ci','CI']].map(([id,title])=>`<button data-filter="${id}" class="${id===activeFilter?'active':''}" aria-pressed="${id===activeFilter}">${title}</button>`).join('')}</div><div class="problem-grid" id="problem-list">${filteredProblems(activeFilter)}</div></section>`;}

export function filteredProblems(activeFilter='all'){return recipes.filter(r=>activeFilter==='all'||r.phase===activeFilter).map(problemCard).join('');}

export function recipe(id,{context={}}={}){
 const r=recipes.find(x=>x.id===id);if(!r)return notFound();
 return breadcrumb('fix','Fix a problem')+pageHead('TROUBLESHOOT / '+e(r.phase.toUpperCase()),e(r.title),e(r.summary))+`<div class="article-layout"><article class="article"><div class="meta"><span class="pill">${e(r.phase)}</span>${r.risk?`<span class="pill">${e(r.risk)}</span>`:''}<span class="reading-time">Source reviewed ${r.reviewed}</span></div><h2>What you are seeing</h2>${command(r.symptom,'Representative symptom; wording varies','Example')}<h2>What it means</h2><p>${e(r.meaning)}</p><h2>Check first</h2><ol>${r.checks.map(x=>`<li>${e(x)}</li>`).join('')}</ol>${r.command?command(r.command,r.effect):''}${r.branch?lockBranch():''}${r.workflow?`<a class="button" href="#workflow/${e(r.workflow)}">Practise this move locally →</a>`:''}<h2>Choose the matching next step</h2><ol>${r.resolution.map(x=>`<li>${e(x)}</li>`).join('')}</ol><div class="callout success"><strong>How to verify</strong><p>${e(r.verify)}</p></div><div class="callout warning"><strong>When to stop</strong><p>${e(r.stop)}</p></div><details class="advanced-only"><summary>Context and limits</summary><p>${e(r.version)}. This guide is diagnostic guidance, not a complete provider/backend recovery procedure. Follow the exact version’s official documentation and your team’s change process.</p></details>${renderContext(context)}<h2>If it still fails</h2><p>Record the failing command, Terraform and provider versions, backend and execution context. Keep the full diagnostic securely, remove sensitive values before sharing, and ask the responsible project or platform owner to review the evidence.</p>${sourceLink(r.source)}<div class="lesson-next"><a class="button" href="#fix">← Browse problems</a><button class="button" data-share>Copy topic link</button></div></article><aside class="aside"><div class="aside-inner"><h3>Before any change</h3><p>Know the working directory, state context and target identity. Check whether another operation is running.</p><h3>Three separate things</h3><p>Restoring configuration, restoring state and recovering infrastructure or data have different effects.</p><a href="#lesson/mental-model">Understand the mental model →</a><a href="#workflow/review">Review a plan →</a><hr class="section-divider">${sourceLink(r.source)}<p>${e(r.version)}</p></div></aside></div>`;
}

export function lockBranch(){return `<div class="choice-panel"><label for="lock-owner">What do you know about the lock owner?</label><select id="lock-owner"><option value="unknown">I do not know yet</option><option value="active">Another operation is still active</option><option value="abandoned">The operation is confirmed abandoned</option></select><div id="lock-advice" aria-live="polite"><p>Identify the owner and check the execution queue. Do not remove a lock whose ownership is uncertain.</p></div></div>`;}
